#include <torch/extension.h>

torch::Tensor fused_classifier_tail(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_classifier_tail", &fused_classifier_tail,
          "Fused 1x1 conv + ReLU + global average pool (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each block handles one (batch, out_channel) pair.
// Threads cooperatively reduce over all spatial positions (H*W) and
// accumulate the 1x1 conv dot-product with ReLU then divide by H*W.
__global__ void fused_classifier_tail_kernel(
    const float* __restrict__ x,       // [N, C_in, H, W] contiguous NCHW
    const float* __restrict__ weight,  // [C_out, C_in]
    const float* __restrict__ bias,    // [C_out] or nullptr
    float* __restrict__ out,           // [N, C_out]
    int N, int C_in, int H, int W, int C_out
) {
    // blockIdx.x = output channel, blockIdx.y = batch index
    int oc = blockIdx.x;
    int n  = blockIdx.y;
    if (oc >= C_out || n >= N) return;

    int HW = H * W;
    const float* w_row = weight + oc * C_in;  // weight[oc, :]

    float thread_sum = 0.0f;

    // Each thread handles a stripe of spatial positions
    for (int hw = threadIdx.x; hw < HW; hw += blockDim.x) {
        int h = hw / W;
        int w = hw % W;
        float dot = 0.0f;
        // Accumulate over input channels (1x1 conv)
        for (int ic = 0; ic < C_in; ++ic) {
            // NCHW indexing: x[n, ic, h, w]
            float xval = x[((n * C_in + ic) * H + h) * W + w];
            dot += xval * w_row[ic];
        }
        if (bias) dot += bias[oc];
        // ReLU
        dot = dot > 0.0f ? dot : 0.0f;
        thread_sum += dot;
    }

    // Block-level reduction in shared memory
    extern __shared__ float smem[];
    smem[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride)
            smem[threadIdx.x] += smem[threadIdx.x + stride];
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        out[n * C_out + oc] = smem[0] / (float)HW;
    }
}

torch::Tensor fused_classifier_tail(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N, C, H, W)");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D");
    TORCH_CHECK(weight.size(2) == 1 && weight.size(3) == 1, "weight must be 1x1 kernel");

    // Make sure x is contiguous in NCHW order for the kernel
    auto x_c = x.contiguous();

    int N    = x_c.size(0);
    int C_in = x_c.size(1);
    int H    = x_c.size(2);
    int W    = x_c.size(3);
    int C_out = weight.size(0);

    TORCH_CHECK(weight.size(1) == C_in, "weight C_in mismatch");

    auto weight_c = weight.contiguous();
    auto bias_c   = bias.defined() ? bias.contiguous() : torch::Tensor();

    auto out = torch::empty({N, C_out}, x_c.options());

    // One block per (out_channel, batch), threads reduce over HW
    int threads = 256;
    dim3 grid(C_out, N);
    size_t smem = threads * sizeof(float);

    fused_classifier_tail_kernel<<<grid, threads, smem>>>(
        x_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_c.defined() ? bias_c.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        N, C_in, H, W, C_out
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
        :param num_classes: Number of output classes
        """
        self.features = nn.Sequential(
        nn.Conv2d(3, 96, kernel_size=7, stride=2),
        nn.ReLU(inplace=True),
        nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
        FireModule(96, 16, 64, 64),
        FireModule(128, 16, 64, 64),
        FireModule(128, 32, 128, 128),
        nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
        FireModule(256, 32, 128, 128),
        FireModule(256, 48, 192, 192),
        FireModule(384, 48, 192, 192),
        FireModule(384, 64, 256, 256),
        nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
        FireModule(512, 64, 256, 256),
        )
        self.classifier = nn.Sequential(
        nn.Dropout(p=0.0),
        nn.Conv2d(512, num_classes, kernel_size=1),
        nn.ReLU(inplace=True),
        nn.AdaptiveAvgPool2d((1, 1))
        )
        torch.backends.cudnn.benchmark = True
        self.features = self.features.to(memory_format=torch.channels_last)
        self.classifier = self.classifier.to(memory_format=torch.channels_last)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        """
        :param x: Input tensor, shape (batch_size, 3, height, width)
        :return: Output tensor, shape (batch_size, num_classes)
        """
        if x.is_cuda:
            x = x.contiguous(memory_format=torch.channels_last)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.features(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        # Fused: 1x1 conv + ReLU + global average pool -> [N, num_classes]
                conv_layer = self.classifier[1]
                if (x.is_cuda and x.dtype == torch.float32
                        and isinstance(conv_layer, torch.nn.Conv2d)
                        and conv_layer.kernel_size == (1, 1)
                        and conv_layer.bias is not None):
                    x = _stark_get_extension().fused_classifier_tail(
                        x, conv_layer.weight, conv_layer.bias
                    )
                else:
                    x = self.classifier(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # If fused path produced 2D output [N, C], return directly.
