CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused 1x1 conv + ReLU + global average pool kernel.
// Grid: (num_classes, batch_size), Block: up to 256 threads.
// Each block computes out[n, cls] = mean over H*W of relu(sum_c(x[n,c,h,w]*w[cls,c]) + bias[cls])
__global__ void fused_classifier_tail_kernel(
    const float* __restrict__ x,      // [N, C, H, W] contiguous NCHW
    const float* __restrict__ weight,  // [K, C, 1, 1] contiguous
    const float* __restrict__ bias,    // [K]
    float* __restrict__ out,           // [N, K]
    int N, int C, int H, int W, int K
) {
    int cls = blockIdx.x;  // output class index
    int n   = blockIdx.y;  // batch index
    if (cls >= K || n >= N) return;

    int HW = H * W;
    int threads = blockDim.x;
    int tid = threadIdx.x;

    extern __shared__ float smem[];

    // Weight row for this class: weight[cls, :, 0, 0]
    const float* w_cls = weight + cls * C;
    // Input for this batch: x[n, :, :, :]
    const float* x_n = x + n * C * HW;

    float local_sum = 0.0f;
    // Each thread handles a subset of spatial positions
    for (int hw = tid; hw < HW; hw += threads) {
        float val = bias[cls];
        // Dot product over input channels
        for (int c = 0; c < C; c++) {
            val += x_n[c * HW + hw] * w_cls[c];
        }
        // ReLU
        local_sum += (val > 0.0f) ? val : 0.0f;
    }

    smem[tid] = local_sum;
    __syncthreads();

    // Block reduction
    for (int stride = threads >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            smem[tid] += smem[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[n * K + cls] = smem[0] / (float)HW;
    }
}

torch::Tensor fused_classifier_tail_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
) {
    // Ensure contiguous NCHW
    x = x.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int K = weight.size(0);

    auto out = torch::empty({N, K}, x.options());

    int threads = 256;
    // Pad threads to power of 2 for reduction
    int HW = H * W;
    // Choose thread count: smallest power of 2 >= min(HW, 256)
    int t = 1;
    while (t < HW && t < 256) t <<= 1;
    threads = t;

    dim3 grid(K, N);
    dim3 block(threads);
    size_t smem_bytes = threads * sizeof(float);

    fused_classifier_tail_kernel<<<grid, block, smem_bytes>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W, K
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
        :param num_classes: Number of output classes
        """
        self.features = nn.Sequential(
        nn.Conv2d(3, 96, kernel_size=7, stride=2),
        nn.ReLU(inplace=True),
