// Each block handles one (batch, out_channel) pair.
// Threads cooperatively reduce over all spatial positions (H*W) and
// accumulate the 1x1 conv dot-product with ReLU then divide by H*W.
__global__ void fused_classifier_tail_kernel(
    const float* __restrict__ x,       // [N, C_in, H, W] contiguous NCHW
    const float* __restrict__ weight,  // [C_out, C_in]
    const float* __restrict__ bias,    // [C_out] or nullptr
    float* __restrict__ out,           // [N, C_out]
    int N, int C_in, int H, int W, int C_out
) {
    // blockIdx.x = output channel, blockIdx.y = batch index
    int oc = blockIdx.x;
    int n  = blockIdx.y;
    if (oc >= C_out || n >= N) return;

    int HW = H * W;
    const float* w_row = weight + oc * C_in;  // weight[oc, :]

    float thread_sum = 0.0f;

    // Each thread handles a stripe of spatial positions
    for (int hw = threadIdx.x; hw < HW; hw += blockDim.x) {
        int h = hw / W;
        int w = hw % W;
        float dot = 0.0f;
        // Accumulate over input channels (1x1 conv)
        for (int ic = 0; ic < C_in; ++ic) {
            // NCHW indexing: x[n, ic, h, w]
            float xval = x[((n * C_in + ic) * H + h) * W + w];
            dot += xval * w_row[ic];
        }
        if (bias) dot += bias[oc];
        // ReLU
        dot = dot > 0.0f ? dot : 0.0f;
        thread_sum += dot;
    }

    // Block-level reduction in shared memory
    extern __shared__ float smem[];
    smem[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride)
            smem[threadIdx.x] += smem[threadIdx.x + stride];
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        out[n * C_out + oc] = smem[0] / (float)HW;
    }
}

torch::Tensor fused_classifier_tail(
    torch::Tensor x,
